"use client"

import { useState, useEffect } from "react"
import {
  Search,
  ChevronUp,
  ChevronDown,
  Edit,
  Trash2,
  AlertCircle,
  Loader2,
  UserCircle,
  Flag,
  Briefcase,
  Home,
  FileText,
  RefreshCw,
  Download,
  CheckCircle,
  MapPin,
} from "lucide-react"
import axios from "axios"
import { useNavigate } from "react-router-dom"
import * as XLSX from "xlsx"
import Layout from "./Layout"

export default function Selected() {
  const navigate = useNavigate()
  const [searchQuery, setSearchQuery] = useState("")
  const [candidates, setCandidates] = useState([])
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState("")
  const [sortField, setSortField] = useState("First_Name")
  const [sortDirection, setSortDirection] = useState("asc")
  const [isModalOpen, setIsModalOpen] = useState(false)
  const [selectedCandidate, setSelectedCandidate] = useState(null)
  const [email, setEmail] = useState("")
  const [password, setPassword] = useState("")

  const [emplacement, setEmplacement] = useState("") // New state for emplacement
  const [emplacementError, setEmplacementError] = useState("") // Error message for emplacement
  const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false)

  useEffect(() => {
    fetchCandidates()
  }, [])

  const fetchCandidates = async () => {
    setIsLoading(true)
    setError("")
    const token = localStorage.getItem("token")

    if (!token) {
      setError("Authentication required. Please log in.")
      setIsLoading(false)
      return
    }

    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/candidates`, {
        headers: {
          Authorization: `Bearer ${token}`,
          Role: "Deputydirector",
        },
      })
      if (response.data.success) {
        setCandidates(response.data.data.filter((candidate) => candidate.status === "selected"))
      } else {
        setError("Failed to fetch selected candidates: " + response.data.message)
      }
    } catch (err) {
      setError(`Error fetching selected candidates: ${err.response?.data?.message || err.message}`)
      console.error("Fetch selected candidates error:", err)
    } finally {
      setIsLoading(false)
    }
  }

  const validateEmplacement = async (value) => {
    if (!selectedCandidate) return;

    const gender = selectedCandidate.Gender;
    const prefix = gender === "Male" ? "RB" : "RG";
    const regex = new RegExp(`^${prefix}(1[0-6]|[1-9]),([1-4])$`); // RB1-16,1-4 or RG1-16,1-4

    if (!value) {
      setEmplacementError("Emplacement is required.");
      return false;
    }

    if (!regex.test(value)) {
      setEmplacementError(`Emplacement must be in format ${prefix}[1-16],[1-4] (e.g., ${prefix}5,3).`);
      return false;
    }

    // Check if emplacement is already taken
    try {
      const token = localStorage.getItem("token");
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/interns/check-emplacement/${value}`, {
        headers: {
          Authorization: `Bearer ${token}`,
          Role: "Deputydirector",
        },
      });

      if (response.data.taken) {
        setEmplacementError(`Emplacement ${value} is already taken.`);
        return false;
      } else {
        setEmplacementError("");
        return true;
      }
    } catch (err) {
      setEmplacementError("Error checking emplacement: " + (err.response?.data?.message || err.message));
      return false;
    }
  }

  const handleEmplacementChange = async (e) => {
    const value = e.target.value.toUpperCase();
    setEmplacement(value);
    await validateEmplacement(value);
  }

  const handleSort = (field) => {
    if (sortField === field) {
      setSortDirection(sortDirection === "asc" ? "desc" : "asc")
    } else {
      setSortField(field)
      setSortDirection("asc")
    }
  }

  const openModal = (candidate) => {
    setSelectedCandidate(candidate)
    setEmail("")
    setPassword("")
    setEmplacement("")
    setEmplacementError("")
    setError("")
    setIsModalOpen(true)
  }

  const closeModal = () => {
    setIsModalOpen(false)
    setSelectedCandidate(null)
    setEmplacementError("")
  }

  const openDetailsModal = (candidate) => {
    setSelectedCandidate(candidate)
    setIsDetailsModalOpen(true)
  }

  const closeDetailsModal = () => {
    setIsDetailsModalOpen(false)
    setSelectedCandidate(null)
  }

  const handleConfirmPayment = async () => {
  if (!email || !password || !emplacement) {
    setError("Email, password, and emplacement are required.");
    return;
  }

  const isEmplacementValid = await validateEmplacement(emplacement);
  if (!isEmplacementValid) return;

  try {
    const token = localStorage.getItem("token");
    const response = await axios.post(
      `${process.env.REACT_APP_API_URL}/api/interns`,
      {
        candidateId: selectedCandidate._id,
        CFF: selectedCandidate.CFF,
        First_Name: selectedCandidate.First_Name,
        Last_Name: selectedCandidate.Last_Name,
        Gender: selectedCandidate.Gender,
        Nationality: selectedCandidate.Nationality,
        Sector: selectedCandidate.Sector,
        hometown: selectedCandidate.hometown,
        email,
        password,
        phoneNumber: selectedCandidate.phoneNumber || "",
        parentPhoneNumber: selectedCandidate.parentPhoneNumber || "",
        emplacement,
        role: "intern",
      },
      {
        headers: {
          Authorization: `Bearer ${token}`,
          Role: "Deputydirector",
        },
      }
    );

    if (response.data.success) {
      fetchCandidates();
      closeModal();
    }
  } catch (err) {
    setError("Failed to confirm payment and convert to intern: " + (err.response?.data?.message || err.message));
  }
};

  const handleEditCandidate = (id) => {
    navigate(`/EditCandidate/${id}`)
  }

  const handleDeleteCandidate = async (id) => {
    if (window.confirm("Are you sure you want to delete this selected candidate?")) {
      try {
        const token = localStorage.getItem("token")
        await axios.delete(`${process.env.REACT_APP_API_URL}/api/candidates/${id}`, {
          headers: {
            Authorization: `Bearer ${token}`,
            Role: "Deputydirector",
          },
        })
        setCandidates(candidates.filter((c) => c._id !== id))
      } catch (err) {
        setError("Failed to delete candidate: " + (err.response?.data?.message || err.message))
      }
    }
  }

  const filteredAndSortedCandidates = candidates
    .filter((candidate) => {
      const matchesSearch =
        `${candidate.First_Name} ${candidate.Last_Name}`.toLowerCase().includes(searchQuery.toLowerCase()) ||
        candidate.CFF.toLowerCase().includes(searchQuery.toLowerCase()) ||
        candidate.hometown.toLowerCase().includes(searchQuery.toLowerCase())
      return matchesSearch
    })
    .sort((a, b) => {
      if (sortField === "Name") {
        const nameA = `${a.First_Name} ${a.Last_Name}`.toLowerCase()
        const nameB = `${b.First_Name} ${b.Last_Name}`.toLowerCase()
        return sortDirection === "asc" ? nameA.localeCompare(nameB) : nameB.localeCompare(nameA)
      }
      const valueA = a[sortField] ? a[sortField].toString().toLowerCase() : ""
      const valueB = b[sortField] ? b[sortField].toString().toLowerCase() : ""
      return sortDirection === "asc" ? valueA.localeCompare(valueB) : valueB.localeCompare(valueA)
    })

const handleExportToExcel = () => {
  const exportData = filteredAndSortedCandidates.map((candidate) => {
    const criteriaData = candidate.criteria.reduce((acc, crit) => {
      const criterionName = crit.criterionId?.name || "Critère inconnu";
      acc[criterionName] = `${crit.description} (${crit.points} points)`;
      return acc;
    }, {});
    return {
      CFF: candidate.CFF || "",
      "First Name": candidate.First_Name || "",
      "Last Name": candidate.Last_Name || "",
      Gender: candidate.Gender || "",
      Nationality: candidate.Nationality || "",
      Sector: candidate.Sector || "",
      Hometown: candidate.hometown || "",
      Note: candidate.Note || "",
      Observation: candidate.Observation || "",
      "Geographic Criteria": candidate.geographic_criteria || "",
      Status: candidate.status || "",
      "Created At": candidate.createdAt
        ? new Date(candidate.createdAt).toLocaleString()
        : "",
      "Updated At": candidate.updatedAt
        ? new Date(candidate.updatedAt).toLocaleString()
        : "",
      "Phone Number": candidate.phoneNumber || "",
      "Parent Phone Number": candidate.parentPhoneNumber || "",
      ...criteriaData,
    };
  });

  const ws = XLSX.utils.json_to_sheet(exportData);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "SelectedCandidates");
  XLSX.writeFile(wb, "Selected_Candidates_Export.xlsx");
};

  const getSortIcon = (field) => {
    if (sortField !== field) return null
    return sortDirection === "asc" ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />
  }

  return (
    <Layout>
      <div className="max-w-7xl mx-auto">
        <div className="bg-white rounded-xl shadow-lg overflow-hidden border border-[#C8A45D/30]/50">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
              <div>
                <h1 className="text-2xl font-bold tracking-tight">Selected Candidates Management</h1>
                <p className="text-white/80 mt-1">View and manage selected candidates</p>
              </div>
            </div>
          </div>

          <div className="p-6 border-b border-[#C8A45D/30]/50">
            <div className="flex flex-col md:flex-row gap-4">
              <div className="relative flex-1">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Search className="h-5 w-5 text-gray-400" />
                </div>
                <input
                  className="w-full bg-white placeholder:text-gray-400 text-gray-900 text-sm border border-[#C8A45D/30] rounded-md pl-10 pr-3 py-2.5 shadow-sm focus:outline-none focus:ring-2 focus:ring-[#00717F]/50 focus:border-transparent transition-all"
                  placeholder="Search by name, CFF, or hometown..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              <div className="flex items-center gap-2">
                <button
                  onClick={fetchCandidates}
                  className="px-3 py-2 border border-[#C8A45D/30] rounded-md shadow-sm hover:bg-[#C8A45D/20]/50 flex items-center gap-2 text-sm text-[#00717F] transition-colors"
                >
                  <RefreshCw className="h-4 w-4" />
                  Refresh
                </button>
                <button
                  onClick={handleExportToExcel}
                  className="px-3 py-2 border border-[#C8A45D/30] rounded-md shadow-sm hover:bg-[#C8A45D/20]/50 flex items-center gap-2 text-sm text-[#00717F] transition-colors"
                >
                  <Download className="h-4 w-4" />
                  Export
                </button>
              </div>
            </div>
          </div>

          {error && (
            <div className="m-6 p-4 bg-red-50 border-l-4 border-red-500 flex items-center gap-3 rounded-r-md shadow-sm">
              <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0" />
              <p className="text-red-700">{error}</p>
            </div>
          )}

          {isLoading ? (
            <div className="flex justify-center items-center h-64">
              <div className="flex flex-col items-center gap-2">
                <Loader2 className="h-8 w-8 text-[#00717F] animate-spin" />
                <p className="text-gray-500">Loading selected candidates...</p>
              </div>
            </div>
          ) : filteredAndSortedCandidates.length === 0 ? (
            <div className="flex flex-col justify-center items-center h-64 text-gray-500">
              <UserCircle className="h-16 w-16 text-gray-300 mb-2" />
              <p className="mb-2">No selected candidates found</p>
            </div>
          ) : (
            <div className="overflow-x-auto p-6">
              <table className="min-w-full divide-y divide-[#C8A45D/30]/50">
                <thead className="bg-[#F5F6FA]">
                  <tr>
                    <th
                      className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider cursor-pointer hover:bg-[#C8A45D/20]/50 transition-colors"
                      onClick={() => handleSort("CFF")}
                    >
                      <div className="flex items-center gap-1">CFF {getSortIcon("CFF")}</div>
                    </th>
                    <th
                      className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider cursor-pointer hover:bg-[#C8A45D/20]/50 transition-colors"
                      onClick={() => handleSort("Name")}
                    >
                      <div className="flex items-center gap-1">Name {getSortIcon("Name")}</div>
                    </th>
                    <th
                      className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider cursor-pointer hover:bg-[#C8A45D/20]/50 transition-colors"
                      onClick={() => handleSort("Gender")}
                    >
                      <div className="flex items-center gap-1">Gender {getSortIcon("Gender")}</div>
                    </th>
                    <th
                      className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider cursor-pointer hover:bg-[#C8A45D/20]/50 transition-colors"
                      onClick={() => handleSort("Nationality")}
                    >
                      <div className="flex items-center gap-1">Nationality {getSortIcon("Nationality")}</div>
                    </th>
                    <th
                      className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider cursor-pointer hover:bg-[#C8A45D/20]/50 transition-colors"
                      onClick={() => handleSort("Sector")}
                    >
                      <div className="flex items-center gap-1">Sector {getSortIcon("Sector")}</div>
                    </th>
                    <th
                      className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider cursor-pointer hover:bg-[#C8A45D/20]/50 transition-colors"
                      onClick={() => handleSort("hometown")}
                    >
                      <div className="flex items-center gap-1">Hometown {getSortIcon("hometown")}</div>
                    </th>
                    <th
                      className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider cursor-pointer hover:bg-[#C8A45D/20]/50 transition-colors"
                      onClick={() => handleSort("Note")}
                    >
                      <div className="flex items-center gap-1">Note {getSortIcon("Note")}</div>
                    </th>
                    <th className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider">
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-[#C8A45D/30]/30">
                  {filteredAndSortedCandidates.map((candidate) => (
                    <tr
                      key={candidate._id}
                      className="hover:bg-[#F5F6FA]/50 transition-colors bg-yellow-100/70 border-l-4 border-l-yellow-400"
                    >
                      <td className="py-4 px-4 text-sm font-medium text-gray-900">{candidate.CFF}</td>
                      <td className="py-4 px-4">
                        <div className="flex items-center">
                          <div className="h-9 w-9 rounded-full bg-gradient-to-r from-[#00717F] to-[#C8A45D]/10 flex items-center justify-center text-[#00717F] mr-3 shadow-sm">
                            <UserCircle className="h-5 w-5" />
                          </div>
                          <div className="text-sm font-medium text-gray-900">
                            {candidate.First_Name} {candidate.Last_Name}
                          </div>
                        </div>
                      </td>
                      <td className="py-4 px-4 text-sm text-#333333 flex items-center gap-2">{candidate.Gender}</td>
                      <td className="py-4 px-4 text-sm text-#333333">
                        <div className="flex items-center gap-2">
                          <Flag className="h-4 w-4 text-[#00717F]/60" />
                          {candidate.Nationality}
                        </div>
                      </td>
                      <td className="py-4 px-4 text-sm text-#333333">
                        <div className="flex items-center gap-2">
                          <Briefcase className="h-4 w-4 text-[#00717F]/60" />
                          {candidate.Sector}
                        </div>
                      </td>
                      <td className="py-4 px-4 text-sm text-#333333">
                        <div className="flex items-center gap-2">
                          <Home className="h-4 w-4 text-[#00717F]/60" />
                          {candidate.hometown}
                        </div>
                      </td>
                      <td className="py-4 px-4 text-sm text-#333333 max-w-[200px]">
                        <div className="flex items-center gap-2">
                          <FileText className="h-4 w-4 text-[#00717F]/60 flex-shrink-0" />
                          <span className="truncate" title={candidate.Note || "No notes available"}>
                            {candidate.Note || "No notes available"}
                          </span>
                        </div>
                      </td>
                      <td className="py-4 px-4 text-sm text-#333333">
                        <div className="flex items-center gap-2 justify-end">
                          <button
                            onClick={() => openModal(candidate)}
                            className="p-2 text-green-600 hover:bg-green-50 rounded-full transition-colors shadow-sm"
                            aria-label="Confirm payment"
                          >
                            <CheckCircle className="h-5 w-5" />
                          </button>
                          <button
                            onClick={() => handleEditCandidate(candidate._id)}
                            className="p-2 text-blue-600 hover:bg-blue-50 rounded-full transition-colors shadow-sm"
                            aria-label="Edit candidate"
                          >
                            <Edit className="h-5 w-5" />
                          </button>
                          <button
                            onClick={() => handleDeleteCandidate(candidate._id)}
                            className="p-2 text-red-600 hover:bg-red-50 rounded-full transition-colors shadow-sm"
                            aria-label="Delete candidate"
                          >
                            <Trash2 className="h-5 w-5" />
                          </button>
                          <button
                            onClick={() => openDetailsModal(candidate)}
                            className="p-2 text-#333333 hover:bg-gray-50 rounded-full transition-colors shadow-sm"
                            aria-label="View Details"
                          >
                            <UserCircle className="h-5 w-5" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>

      {/* Modal for Email, Password, and Emplacement */}
{isModalOpen && selectedCandidate && (
  <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
    <div className="bg-white rounded-lg p-6 w-full max-w-md shadow-xl border border-[#C8A45D/30]">
      <h2 className="text-xl font-bold text-[#00717F] mb-4">Confirm Payment and Convert to Intern</h2>
      <p className="text-#333333 mb-4">
        Please provide details for {selectedCandidate.First_Name} {selectedCandidate.Last_Name}.
      </p>
      <div className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
          <div className="relative">
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full border border-[#C8A45D/30] rounded-md p-2 pl-9 focus:outline-none focus:ring-2 focus:ring-[#00717F] focus:border-transparent"
              placeholder="Enter email"
            />
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <svg
                xmlns="http://www.w3.org/2000/svg"
                className="h-4 w-4 text-gray-400"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"
                />
              </svg>
            </div>
          </div>
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Password</label>
          <div className="relative">
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full border border-[#C8A45D/30] rounded-md p-2 pl-9 focus:outline-none focus:ring-2 focus:ring-[#00717F] focus:border-transparent"
              placeholder="Enter password"
            />
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <svg
                xmlns="http://www.w3.org/2000/svg"
                className="h-4 w-4 text-gray-400"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"
                />
              </svg>
            </div>
          </div>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Emplacement</label>
          <div className="relative">
            <input
              type="text"
              value={emplacement}
              onChange={handleEmplacementChange}
              className="w-full border border-[#C8A45D/30] rounded-md p-2 pl-9 focus:outline-none focus:ring-2 focus:ring-[#00717F] focus:border-transparent"
              placeholder={`e.g., ${selectedCandidate.Gender === "Male" ? "RB5,3" : "RG5,3"}`}
            />
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <MapPin className="h-4 w-4 text-gray-400" />
            </div>
          </div>
          {emplacementError && (
            <p className="mt-1 text-sm text-red-600">{emplacementError}</p>
          )}
        </div>
      </div>
      {error && (
        <div className="mt-4 p-2 bg-red-50 border-l-4 border-red-500 text-red-700 text-sm rounded-r-md">
          {error}
        </div>
      )}
      <div className="mt-6 flex justify-end gap-2">
        <button
          onClick={closeModal}
          className="px-4 py-2 bg-gray-200 text-gray-700 rounded-md hover:bg-gray-300 transition-colors"
        >
          Cancel
        </button>
        <button
          onClick={handleConfirmPayment}
          className={`px-4 py-2 rounded-md text-white transition-colors ${
            emplacementError || !email || !password || !emplacement
              ? "bg-gray-400 cursor-not-allowed"
              : "bg-green-600 hover:bg-green-700"
          }`}
          disabled={emplacementError || !email || !password || !emplacement}
        >
          Confirm
        </button>
      </div>
    </div>
  </div>
)}
{/* Details Modal */}
{isDetailsModalOpen && selectedCandidate && (
  <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
    <div className="bg-white rounded-lg p-6 w-full max-w-lg shadow-xl max-h-[80vh] overflow-y-auto border border-[#C8A45D/30]">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-xl font-bold text-[#00717F]">Détails du Candidat Sélectionné</h2>
        <div className="px-2 py-1 bg-yellow-100 text-yellow-800 text-xs font-medium rounded-full">Sélectionné</div>
      </div>

      <div className="bg-[#F5F6FA]/50 p-4 rounded-lg mb-4">
        <div className="flex items-center gap-3 mb-3">
          <div className="h-12 w-12 rounded-full bg-gradient-to-r from-[#00717F] to-[#C8A45D]/10 flex items-center justify-center text-[#00717F] shadow-sm">
            <UserCircle className="h-7 w-7" />
          </div>
          <div>
            <h3 className="text-lg font-semibold text-gray-900">
              {selectedCandidate.First_Name} {selectedCandidate.Last_Name}
            </h3>
            <p className="text-sm text-gray-500">CFF : {selectedCandidate.CFF}</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-gray-700">
        <div className="space-y-3 border-r border-[#C8A45D/30]/30 pr-4">
          <p>
            <strong className="text-[#00717F]">Genre :</strong>{" "}<br></br>
            {selectedCandidate.Gender === "Male" ? "Homme" : "Femme"}
          </p>
          <p>
            <strong className="text-[#00717F]">Nationalité :</strong>{" "}<br></br>
            {selectedCandidate.Nationality || "N/A"}
          </p>
          <p>
            <strong className="text-[#00717F]">Secteur :</strong>{" "}<br></br>
            {selectedCandidate.Sector || "N/A"}
          </p>
          <p>
            <strong className="text-[#00717F]">Ville d'origine :</strong>{" "}<br></br>
            {selectedCandidate.hometown || "N/A"}
          </p>
          <p>
            <strong className="text-[#00717F]">Note :</strong>{" "}<br></br>
            {selectedCandidate.Note || "Aucune note disponible"}
          </p>
          <p>
            <strong className="text-[#00717F]">Observation :</strong>{" "}<br></br>
            {selectedCandidate.Observation || "N/A"}
          </p>
          <p>
            <strong className="text-[#00717F]">Numéro de téléphone :</strong>{" "}<br></br>
            {selectedCandidate.phoneNumber || "N/A"}
          </p>
          <p>
            <strong className="text-[#00717F]">Numéro de téléphone des parents :</strong>{" "}<br></br>
            {selectedCandidate.parentPhoneNumber || "N/A"}
          </p>
        </div>
        <div className="space-y-3">
          {selectedCandidate.criteria && selectedCandidate.criteria.length > 0 ? (
            selectedCandidate.criteria.map((crit, index) => (
              <p key={index}>
                <strong className="text-[#00717F]">
                  {crit.criterionId?.name || "Critère inconnu"} :
                </strong>{" "}<br></br>
                {crit.description} ({crit.points} points)
              </p>
            ))
          ) : (
            <p>Aucun critère défini</p>
          )}
          <p>
            <strong className="text-[#00717F]">Critères géographiques :</strong>{" "}<br></br>
            {selectedCandidate.geographic_criteria || "0"} points
          </p>
          <p>
            <strong className="text-[#00717F]">Statut :</strong>{" "}<br></br>
            <span className="px-2 py-0.5 bg-yellow-100 text-yellow-800 text-xs font-medium rounded-full">
              {selectedCandidate.status || "Sélectionné"}
            </span>
          </p>
        </div>
      </div>

      <div className="mt-6 pt-4 border-t border-[#C8A45D/30]/30 flex justify-between items-center">
        <div className="text-xs text-gray-500">
          <p>Créé : {new Date(selectedCandidate.createdAt).toLocaleString()}</p>
          <p>Mis à jour : {new Date(selectedCandidate.updatedAt).toLocaleString()}</p>
        </div>
        <button
          onClick={closeDetailsModal}
          className="px-4 py-2 bg-[#00717F] text-white rounded-md hover:bg-[#00717F]/90 transition-colors"
        >
          Fermer
        </button>
      </div>
    </div>
  </div>
)}
    </Layout>
  )
}
